This PowerShell script is designed for defensive security auditing. It requires **Administrator privileges** to read the Security log and usually the **Sysmon** log (if installed).

### Prerequisites
1.  Run PowerShell as Administrator.
2.  (Optional but recommended) Install Sysmon. The script handles cases where Sysmon is not installed gracefully.

### The Script

```powershell
<#
.SYNOPSIS
    Lateral Movement & Suspicious Activity Scanner for Windows Event Logs.
.DESCRIPTION
    Scans Security and Sysmon logs for indicators of lateral movement and suspicious execution.
    Checks: 4624 (Logons), 4688 (Process Creation), 4672 (Admin Rights), 10 (Sysmon/WMI).
.EXAMPLE
    .\Invoke-LMScan.ps1 -HoursBack 24 -BusinessStart 8 -BusinessEnd 17
#>

param(
    [int]$HoursBack = 24,
    [int]$BusinessStart = 8,  # 8:00 AM
    [int]$BusinessEnd = 17    # 5:00 PM
)

# ---------------------------------------------------------
# 1. PREREQUISITE CHECKS
# ---------------------------------------------------------

# Check for Admin Rights (Required for Security Log access)
$CurrentUser = [Security.Principal.WindowsIdentity]::GetCurrent()
$Principal = New-Object Security.Principal.WindowsPrincipal($CurrentUser)
if (-not $Principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Write-Error "This script must be run as Administrator."
    exit 1
}

Write-Host "-----------------------------------------" -ForegroundColor Cyan
Write-Host "  Lateral Movement & Execution Scanner" -ForegroundColor Cyan
Write-Host "  Scanning last $HoursBack hours" -ForegroundColor Cyan
Write-Host "-----------------------------------------" -ForegroundColor Cyan

$StartDate = (Get-Date).AddHours(-$HoursBack)

# ---------------------------------------------------------
# 2. DATA STRUCTURES FOR REPORT
# ---------------------------------------------------------
$Report = @{
    LateralMovement = @()
    SuspiciousExecution = @()
    AdminRecon = @()
    WMIActivity = @()
}

# ---------------------------------------------------------
# 3. FUNCTION: PARSE LOGON TYPE 3 (LATERAL MOVEMENT)
# ---------------------------------------------------------
# Event ID 4624: An account was successfully logged on.
# Logon Type 3 (Network) is the primary indicator of lateral movement (RDP, SMB, PsExec).
# We filter for remote IPs and logons outside business hours.
Write-Host "[INFO] Querying Event ID 4624 (Logon Types)..." -ForegroundColor Yellow

try {
    $LogonEvents = Get-WinEvent -FilterHashtable @{
        LogName='Security'
        ID=4624
        StartTime=$StartDate
    } -MaxEvents 2000 -ErrorAction Stop

    foreach ($Event in $LogonEvents) {
        # Parse XML to get structured data (faster than string parsing)
        $EventXml = [xml]$Event.ToXml()
        $EventData = $EventXml.Event.EventData.Data

        $LogonType = ($EventData | Where-Object { $_.Name -eq 'LogonType' }).'#text'
        $TargetUser = ($EventData | Where-Object { $_.Name -eq 'TargetUserName' }).'#text'
        $IpAddress = ($EventData | Where-Object { $_.Name -eq 'IpAddress' }).'#text'

        # Logic: Is it a Network Logon (Type 3)?
        if ($LogonType -eq "3") {
            # Logic: Is it from a remote source? (Ignore local/loopback)
            if ($IpAddress -ne "-" -and $IpAddress -ne "127.0.0.1" -and $IpAddress -ne "::1" -and ![string]::IsNullOrEmpty($IpAddress)) {

                # Logic: Outside Business Hours?
                $Hour = $Event.TimeCreated.Hour
                if ($Hour -lt $BusinessStart -or $Hour -ge $BusinessEnd) {
                    $Report.LateralMovement += [PSCustomObject]@{
                        Time = $Event.TimeCreated
                        User = $TargetUser
                        SourceIP = $IpAddress
                        LogonType = "3 (Network)"
                        Reason = "Remote Logon Outside Business Hours ($Hour:00)"
                    }
                }
            }
        }
    }
} catch {
    Write-Warning "Could not query Security Log. Ensure running as Admin."
}

# ---------------------------------------------------------
# 4. FUNCTION: PARSE PROCESS CREATION (EXECUTION)
# ---------------------------------------------------------
# Event ID 4688: A new process has been created.
# We look for suspicious parent-child relationships:
# e.g., Rundll32 -> CMD, or Mshta -> Script.
Write-Host "[INFO] Querying Event ID 4688 (Process Creation)..." -ForegroundColor Yellow

try {
    $ProcessEvents = Get-WinEvent -FilterHashtable @{
        LogName='Security'
        ID=4688
        StartTime=$StartDate
    } -MaxEvents 2000 -ErrorAction Stop

    # Suspicious Parent Processes
    $SuspiciousParents = @("rundll32", "mshta", "wmic", "cmstp", "regsvr32", "bitsadmin")
    # Suspicious Child Processes
    $SuspiciousChildren = @("cmd.exe", "powershell.exe", "certutil.exe", "net.exe", "vssadmin.exe", "reg.exe", "net1.exe")

    foreach ($Event in $ProcessEvents) {
        # 4688 Messages are long strings. Regex or Contains is easiest here.
        $Message = $Event.Message

        $IsSuspicious = $false
        $Reason = ""

        # Check Parent -> Child Logic
        foreach ($Parent in $SuspiciousParents) {
            if ($Message -match $Parent) {
                foreach ($Child in $SuspiciousChildren) {
                    if ($Message -match $Child) {
                        $IsSuspicious = $True
                        $Reason = "$Parent spawning $Child"
                        break
                    }
                }
            }
        }

        # Generic check for cmd/powershell spawned by non-system users (often happens via lateral movement tools)
        if ($Message -match "New Process Name.*\\\cmd\.exe" -or $Message -match "New Process Name.*\\\powershell\.exe") {
             # Simple heuristic: if it's not the System account doing it, flag it.
             # Note: $Event.Message parsing for specific user requires regex on the message string.
             $Report.SuspiciousExecution += [PSCustomObject]@{
                Time = $Event.TimeCreated
                EventID = 4688
                Detail = "Cmd/Powershell spawned"
                Reason = "Suspicious Parent-Child Process Chain"
            }
        }

        if ($IsSuspicious) {
            $Report.SuspiciousExecution += [PSCustomObject]@{
                Time = $Event.TimeCreated
                EventID = 4688
                Detail = $Reason
                Reason = "Suspicious Execution"
            }
        }
    }
} catch {}

# ---------------------------------------------------------
# 5. FUNCTION: PARSE ADMIN LOGONS (PRIV ESC / RECON)
# ---------------------------------------------------------
# Event ID 4672: Special privileges assigned to new logon.
# We filter out SYSTEM accounts to find actual human admins logging in.
Write-Host "[INFO] Querying Event ID 4672 (Admin Logons)..." -ForegroundColor Yellow

try {
    $AdminEvents = Get-WinEvent -FilterHashtable @{
        LogName='Security'
        ID=4672
        StartTime=$StartDate
    } -MaxEvents 1000 -ErrorAction Stop

    # Filter out standard service accounts
    $IgnoredAccounts = @("SYSTEM", "LOCAL SERVICE", "NETWORK SERVICE", "ANONYONYMOUS LOGON")

    foreach ($Event in $AdminEvents) {
        $EventXml = [xml]$Event.ToXml()
        $EventData = $EventXml.Event.EventData.Data
        $Account = ($EventData | Where-Object { $_.Name -eq 'SubjectUserName' }).'#text'

        if ($IgnoredAccounts -notcontains $Account) {
             # Check if time is suspicious
             $Hour = $Event.TimeCreated.Hour
             if ($Hour -lt $BusinessStart -or $Hour -ge $BusinessEnd) {
                $Report.AdminRecon += [PSCustomObject]@{
                    Time = $Event.TimeCreated
                    Account = $Account
                    Privilege = "Admin/Special"
                    Reason = "Admin logon outside business hours"
                }
             }
        }
    }
} catch {}

# ---------------------------------------------------------
# 6. FUNCTION: PARSE SYSMON EVENT ID 10 (WMI Activity)
# ---------------------------------------------------------
# Note: Standard Sysmon ID 10 is "ProcessAccess" (often used for LSASS dumping).
